import type { BankQuestion } from "@/lib/bank";

/** Neural Control, Endocrine System and Locomotion (Biology (NEET)): 133 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"bio-neural-endocrine-1","question":"The junction between two neurons through which impulses are transmitted is called a:","options":["Synapse","Node of Ranvier","Axon hillock","Dendron"],"answer":0,"explanation":"A synapse is formed by the membranes of a pre-synaptic and a post-synaptic neuron, which may or may not be separated by a synaptic cleft. Nodes of Ranvier are gaps in the myelin sheath along a single axon.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-2","question":"Which cells of the pancreas secrete insulin?","options":["α-cells of the islets of Langerhans","Zona fasciculata of the adrenal cortex","Acinar cells of the pancreas","β-cells of the islets of Langerhans"],"answer":3,"explanation":"β-cells secrete insulin (lowers blood glucose) and α-cells secrete glucagon (raises it). Acinar cells form the exocrine part that produces pancreatic juice.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-3","question":"In the peripheral nervous system, the myelin sheath around an axon is formed by:","options":["Astrocytes","Oligodendrocytes","Schwann cells","Microglia"],"answer":2,"explanation":"Schwann cells wrap myelinated nerve fibres of the PNS (spinal and cranial nerves); oligodendrocytes do the same in the CNS. Unmyelinated fibres are enclosed by a Schwann cell without a myelin sheath.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-4","question":"When a neuron is at rest (not conducting an impulse), its axonal membrane is comparatively more permeable to:","options":["Na⁺ ions","K⁺ ions","Cl⁻ ions","Negatively charged proteins"],"answer":1,"explanation":"At rest the membrane is more permeable to K⁺ and nearly impermeable to Na⁺ and to the anionic proteins inside; together with the Na⁺–K⁺ pump this leaves the outer surface positive and the inner surface negative (resting potential).","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-5","question":"The centres that control respiration, cardiovascular reflexes and gastric secretions are located in the:","options":["Cerebellum of the hindbrain","Hypothalamus of the forebrain","Medulla oblongata","Pons Varolii"],"answer":2,"explanation":"The medulla oblongata of the hindbrain houses the respiratory rhythm centre and centres for cardiovascular reflexes and gastric secretion. The pons has the pneumotaxic centre that only moderates respiration.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-6","question":"Hypothyroidism during pregnancy leads in the baby to stunted growth, mental retardation, low IQ, abnormal skin and deaf-mutism. This condition is:","options":["Myxoedema","Cretinism","Exophthalmic goitre","Acromegaly"],"answer":1,"explanation":"Cretinism is the result of thyroid hormone deficiency in infancy/foetal life. Myxoedema is adult hypothyroidism; exophthalmic goitre (Graves’ disease) is hyperthyroidism; acromegaly is excess growth hormone in adults.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-7","question":"In skeletal muscle, the protein that binds Ca²⁺ at the start of contraction and thereby exposes the active sites on actin is:","options":["Tropomyosin","Troponin","Myosin light chain","Meromyosin"],"answer":1,"explanation":"Ca²⁺ released from the sarcoplasmic reticulum binds troponin; this shifts tropomyosin and unmasks the myosin-binding sites on F-actin so that cross-bridges can form.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-8","question":"The joint between the atlas and the axis, which allows the head to turn, is a:","options":["Hinge joint","Ball and socket joint","Gliding joint","Pivot joint"],"answer":3,"explanation":"The atlas–axis joint is a pivot joint. Hinge: knee and elbow; ball and socket: shoulder and hip; gliding: between carpals; saddle: carpal–metacarpal of the thumb.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-9","question":"Diabetes insipidus, marked by loss of water through large volumes of dilute urine, is caused by deficiency of:","options":["Insulin from β-cells","Oxytocin","Aldosterone (mineralocorticoid)","Vasopressin (ADH)"],"answer":3,"explanation":"ADH from the neurohypophysis stimulates water reabsorption in the distal tubules and collecting ducts; its deficiency causes diuresis and dehydration. Insulin deficiency causes diabetes mellitus, with glucose in the urine.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-10","question":"The sodium–potassium pump of a neuron transports, per cycle:","options":["3 Na⁺ outward and 2 K⁺ inward","2 Na⁺ outward and 3 K⁺ inward","3 Na⁺ inward and 2 K⁺ outward","Equal numbers of Na⁺ and K⁺ in opposite directions"],"answer":0,"explanation":"The pump moves 3 Na⁺ out for every 2 K⁺ in, maintaining a high K⁺ and low Na⁺ concentration in the axoplasm and contributing to the negative resting potential.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-11","question":"Which statement about electrical synapses is correct?","options":["Current flows directly across closely apposed membranes, so it is faster","They are more common than chemical synapses in the human nervous system","Transmission across them is always inhibitory, never excitatory, in nature","They need neurotransmitters stored in synaptic vesicles to pass the impulse"],"answer":0,"explanation":"At electrical synapses impulse transmission resembles conduction along a single axon and is faster; they are rare in our system. Chemical synapses use neurotransmitters and are the common type.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-12","question":"Erythropoietin, which stimulates the formation of red blood cells, is secreted by:","options":["Cardiac cells of the atrial wall","Juxtaglomerular cells of kidney","Epithelial cells of the thymus","Hepatocytes of the adult liver"],"answer":1,"explanation":"JG cells of the kidney secrete erythropoietin, which acts on bone marrow. The atrial wall secretes ANF; the thymus secretes thymosins.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-13","question":"Excess secretion of growth hormone in adults, especially in middle age, leads to:","options":["Gigantism, with abnormal increase in height","Cushing’s syndrome with a moon face","Dwarfism with stunted bone growth","Acromegaly, with facial disfigurement"],"answer":3,"explanation":"Over-secretion of GH in a growing child causes gigantism; in adults, after the epiphyses have fused, it produces acromegaly (enlarged jaw, hands and feet). Deficiency in childhood causes pituitary dwarfism.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-14","question":"During contraction of a sarcomere, which of the following does NOT change in length?","options":["I band","H zone","A band","The sarcomere as a whole"],"answer":2,"explanation":"Thin filaments slide over the thick filaments, so the I band and H zone shorten and the Z lines come closer, but the A band (length of the myosin filaments) stays constant.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-15","question":"The number of vertebrae in the vertebral column of an adult human, and their regional distribution, is:","options":["33: 7 cervical, 12 thoracic, 5 lumbar, 5 sacral, 4 coccygeal","26: 7 cervical, 12 thoracic, 5 lumbar, 1 sacrum, 1 coccyx","26: 7 cervical, 10 thoracic, 5 lumbar, 2 sacral, 2 coccygeal","24: 7 cervical, 12 thoracic, 5 lumbar, none fused"],"answer":1,"explanation":"NCERT counts 26 vertebrae because the sacral and coccygeal vertebrae are fused into one sacrum and one coccyx. The first vertebra is the atlas; the column protects the spinal cord and supports the head.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-16","question":"Red muscle fibres differ from white fibres in that red fibres:","options":["Have more mitochondria and myoglobin, and resist fatigue by aerobic respiration","Have less myoglobin and so depend mainly on anaerobic glycolysis for ATP","Have more sarcoplasmic reticulum, so they release Ca²⁺ faster and fatigue quickly","Are found only in the heart, as cardiac muscle is red"],"answer":0,"explanation":"Red (aerobic) fibres are rich in myoglobin and mitochondria; white fibres have little myoglobin, fewer mitochondria but abundant sarcoplasmic reticulum and depend on anaerobic processes, so they tire fast.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-17","question":"Graves’ disease (exophthalmic goitre) is characterised by:","options":["Low BMR, weight gain and puffy skin (myxoedema)","Absence of thyroid hormone due to iodine deficiency","Stunted growth and deaf-mutism in infancy (cretinism)","Goitre, protruding eyeballs, high BMR and weight loss"],"answer":3,"explanation":"Graves’ disease is hyperthyroidism: an enlarged gland, exophthalmos, increased BMR and weight loss. Iodine deficiency leads to hypothyroidism with goitre, not Graves’ disease.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-18","question":"Which of these hormones acts through an intracellular receptor and regulates gene expression directly, rather than through a membrane receptor and second messenger?","options":["Insulin","Cortisol","Epinephrine","Glucagon"],"answer":1,"explanation":"Steroid hormones (cortisol, aldosterone, sex steroids), iodothyronines and others that are lipid soluble enter the cell and bind intracellular receptors, forming hormone–receptor complexes that regulate transcription. Peptide hormones and catecholamines bind membrane receptors and use second messengers such as cAMP, IP₃ or Ca²⁺.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-19","question":"How many of the following statements about the nerve impulse are correct?\n(i) At the resting potential the outer surface of the axonal membrane is positively charged relative to the inner surface.\n(ii) Depolarisation is caused by a rapid influx of Na⁺ through voltage-gated channels when the stimulus is applied.\n(iii) Repolarisation follows as K⁺ diffuses out of the axon.\n(iv) The Na⁺–K⁺ pump transports 2 Na⁺ outward for every 3 K⁺ inward.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (ii) and (iii) are correct. (iv) reverses the stoichiometry: the pump moves 3 Na⁺ out and 2 K⁺ in.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-20","question":"Match the hormonal disorder with its cause.\nA. Addison’s disease — 1. Deficiency of thyroid hormones in adults\nB. Myxoedema — 2. Under-secretion of glucocorticoids and mineralocorticoids by the adrenal cortex\nC. Pituitary dwarfism — 3. Deficiency of insulin\nD. Diabetes mellitus — 4. Low secretion of growth hormone in a growing child","options":["A-2, B-1, C-4, D-3","A-1, B-2, C-4, D-3","A-2, B-4, C-1, D-3","A-3, B-1, C-4, D-2"],"answer":0,"explanation":"Addison’s disease: adrenal cortex underactivity leading to altered carbohydrate metabolism and acute weakness; myxoedema: adult hypothyroidism; dwarfism: GH deficiency; diabetes mellitus: prolonged hyperglycaemia from insulin deficiency.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-21","question":"Match the part of the brain with its description.\nA. Corpus callosum — 1. Dorsal part of the midbrain bearing four round swellings (corpora quadrigemina)\nB. Cerebellum — 2. Tract of nerve fibres connecting the two cerebral hemispheres\nC. Midbrain — 3. Very convoluted surface giving additional space for more neurons\nD. Limbic system — 4. Inner parts of the cerebral hemispheres (amygdala, hippocampus) that, with the hypothalamus, regulate emotion and sexual behaviour","options":["A-2, B-3, C-1, D-4","A-2, B-1, C-3, D-4","A-3, B-2, C-1, D-4","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"The corpus callosum links the cerebral hemispheres, the cerebellum is highly folded, the midbrain’s dorsal surface carries the corpora quadrigemina, and the limbic lobe with the hypothalamus governs emotion, motivation and sexual behaviour.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-22","question":"Assertion (A): Parathyroid hormone and calcitonin act antagonistically on blood calcium.\nReason (R): PTH raises Ca²⁺ by stimulating bone resorption, reabsorption of Ca²⁺ by renal tubules and absorption from digested food, whereas thyrocalcitonin lowers blood Ca²⁺.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"PTH is hypercalcaemic and is regulated by blood Ca²⁺ levels; TCT from the thyroid is hypocalcaemic. Together with vitamin D they maintain calcium homeostasis.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-23","question":"How many of the following statements about skeletal muscle contraction are correct?\n(i) The globular head of myosin has ATPase activity and binding sites for ATP and actin.\n(ii) The thin filament has two F-actin strands helically wound together, with tropomyosin and troponin.\n(iii) Ca²⁺ binding to troponin exposes the active sites on actin for myosin heads.\n(iv) During contraction the H zone becomes wider.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (ii) and (iii) are correct. (iv) is false: as actin slides toward the centre of the A band, the H zone (region with myosin only) narrows or disappears.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-24","question":"Which of the following hormones is released from the pituitary but is NOT synthesised there?","options":["Prolactin","Thyroid stimulating hormone","Oxytocin","Melanocyte stimulating hormone"],"answer":2,"explanation":"Oxytocin and vasopressin are synthesised by hypothalamic neurons, transported along axons and stored/released from the neurohypophysis (pars nervosa). Prolactin, TSH and MSH are made in the adenohypophysis itself.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-25","question":"Which of the following is NOT an effect of glucocorticoids such as cortisol?","options":["Stimulation of gluconeogenesis, lipolysis and proteolysis","Suppression of the immune response and anti-inflammatory action","Stimulation of RBC production and maintenance of cardiovascular and kidney function","Stimulation of Na⁺ reabsorption and K⁺ excretion by the renal tubules"],"answer":3,"explanation":"Regulation of Na⁺ and K⁺ balance (and thereby water and blood pressure) is the role of mineralocorticoids, chiefly aldosterone. Cortisol affects carbohydrate metabolism, inhibits cellular uptake of amino acids, suppresses inflammation and immunity, and stimulates erythropoiesis.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-26","question":"How many of the following statements about the human skeleton are correct?\n(i) The first seven pairs of ribs are true ribs, attached to the sternum by hyaline cartilage.\n(ii) The 8th, 9th and 10th pairs do not reach the sternum directly and are called vertebrochondral (false) ribs.\n(iii) The 11th and 12th pairs are floating ribs.\n(iv) The skull consists of 22 bones, of which 8 are cranial bones and 14 are facial bones.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: ribs 1–7 are true ribs, 8–10 are vertebrochondral (false) ribs, 11–12 are floating ribs, and the 22 skull bones are 8 cranial and 14 facial (ear ossicles and hyoid counted separately).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-27","question":"Match the hormone with its chemical nature.\nA. Thyroxine — 1. Steroid\nB. Epinephrine — 2. Iodothyronine\nC. Cortisol — 3. Peptide/protein\nD. Glucagon — 4. Amino-acid derivative (catecholamine)","options":["A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3","A-3, B-4, C-1, D-2","A-1, B-4, C-2, D-3"],"answer":0,"explanation":"Hormones are peptides (insulin, glucagon, pituitary and hypothalamic hormones), steroids (cortisol, aldosterone, sex hormones), iodothyronines (T₃, T₄) or amino-acid derivatives (epinephrine, norepinephrine).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-28","question":"How many of the following statements about the thyroid gland are correct?\n(i) It is composed of four lobes connected by an isthmus.\n(ii) Thyroid follicles secrete tetraiodothyronine (T₄) and triiodothyronine (T₃), while thyrocalcitonin is a steroid hormone of the same gland.\n(iii) Iodine is essential for the normal rate of hormone synthesis in the thyroid.\n(iv) Deficiency of iodine in the diet results in hyperthyroidism and weight loss.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only (iii) is correct. The thyroid has two lobes joined by an isthmus (four is the number of parathyroids), thyrocalcitonin is a protein hormone, and iodine deficiency causes hypothyroidism and goitre.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-29","question":"How many of the following hormone–action pairs are correctly matched?\n(i) Gastrin — stimulates secretion of water and bicarbonate by the pancreas\n(ii) Secretin — stimulates secretion of HCl and pepsinogen\n(iii) CCK — stimulates secretion of pancreatic enzymes and bile\n(iv) GIP — stimulates gastric secretion and motility","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only (iii) is correct. The actions of gastrin and secretin are swapped: gastrin stimulates HCl and pepsinogen, secretin stimulates water and bicarbonate from the pancreas. GIP inhibits gastric secretion and motility.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-30","question":"Match the disorder of the muscular or skeletal system with its description.\nA. Myasthenia gravis — 1. Progressive degeneration of skeletal muscle, mostly due to a genetic disorder\nB. Muscular dystrophy — 2. Auto-immune disorder affecting the neuromuscular junction leading to fatigue and paralysis\nC. Tetany — 3. Inflammation of joints\nD. Gout — 4. Rapid spasms (wild contractions) due to low Ca²⁺ in body fluid\nE. Arthritis — 5. Inflammation of joints due to accumulation of uric acid crystals","options":["A-2, B-1, C-4, D-5, E-3","A-1, B-2, C-4, D-3, E-5","A-2, B-1, C-5, D-4, E-3","A-4, B-1, C-2, D-5, E-3"],"answer":0,"explanation":"Myasthenia gravis is autoimmune; muscular dystrophy is genetic; tetany is hypocalcaemic spasm; gout is uric-acid arthritis; osteoporosis (not listed) is decreased bone mass, commonly from low oestrogen.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-31","question":"The functional unit of contraction of a skeletal muscle fibre is the:","options":["Sarcoplasmic reticulum","Myoglobin","Fascicle","Sarcomere"],"answer":3,"explanation":"The portion of a myofibril between two successive Z lines is a sarcomere, the functional unit of contraction.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-32","question":"The pineal gland secretes melatonin, which mainly helps in:","options":["Raising blood calcium by bone resorption","Regulating the diurnal (24-hour) rhythm","Differentiation of T-lymphocytes in the thymus","Stimulating milk ejection during suckling"],"answer":1,"explanation":"Melatonin maintains the normal sleep-wake cycle and body temperature rhythm, and also influences metabolism, pigmentation, the menstrual cycle and defence.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-33","question":"Thymosins, secreted by the thymus, play a major role in:","options":["Conversion of glycogen to glucose","Reabsorption of water in the kidney","Contraction of the uterus","Differentiation of T-lymphocytes"],"answer":3,"explanation":"Thymosins help T-lymphocytes differentiate (cell-mediated immunity) and promote antibody production. The thymus degenerates in old people, weakening immunity.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-34","question":"The neurotransmitter released at the neuromuscular junction that generates an action potential in the sarcolemma is:","options":["Acetylcholine","Serotonin (5-HT)","Dopamine","Adrenaline"],"answer":0,"explanation":"A neural signal reaching the motor end plate releases acetylcholine, which generates an action potential in the sarcolemma that spreads through the muscle fibre.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-35","question":"Somatostatin, a hormone of the hypothalamus, inhibits the release of:","options":["Growth hormone from the pituitary","Gonadotrophins from the pituitary","Oxytocin from the posterior pituitary","Insulin from the pancreas only"],"answer":0,"explanation":"Somatostatin from the hypothalamus inhibits the release of growth hormone, whereas GnRH stimulates the release of gonadotrophins.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-36","question":"The corpus luteum, formed from the ruptured Graafian follicle, mainly secretes:","options":["Oestrogen only","Relaxin only, throughout the cycle","Luteinising hormone","Progesterone"],"answer":3,"explanation":"The corpus luteum secretes mainly progesterone, which supports pregnancy and acts on the mammary glands. Growing follicles secrete oestrogens.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-37","question":"Gout is inflammation of the joints due to accumulation of:","options":["Calcium oxalate in muscles","Lactic acid","Urea in the synovial fluid","Uric acid crystals"],"answer":3,"explanation":"In gout uric acid crystals accumulate in joints. Arthritis is inflammation of joints, and osteoporosis is reduced bone mass with increased fractures.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-38","question":"The limbic system, which along with the hypothalamus regulates sexual behaviour, emotional reactions (excitement, pleasure, rage, fear) and motivation, includes:","options":["Cerebellum and the pons","Corpora quadrigemina of midbrain","Amygdala and hippocampus","Medulla and spinal cord"],"answer":2,"explanation":"The inner parts of the cerebral hemispheres together with deep structures like the amygdala and hippocampus form the limbic system.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-39","question":"How many of the following statements about the human brain are correct?\n(i) The cerebral cortex appears greyish because of concentrated neuron cell bodies and is called grey matter.\n(ii) The cortex contains motor areas, sensory areas and large regions that are neither clearly sensory nor motor, called association areas.\n(iii) The myelinated fibres of tracts form the inner part of the cerebral hemisphere, the white matter.\n(iv) The midbrain lies between the thalamus/hypothalamus of the forebrain and the pons of the hindbrain.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Association areas are responsible for complex functions like intersensory associations, memory and communication.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-40","question":"Match the skeletal structure with its description.\nList I: (A) Glenoid cavity (B) Acetabulum (C) Acromion (D) Patella\nList II: (1) Cup-shaped bone covering the knee ventrally (2) Expanded process at the end of the spine of the scapula (3) Cavity at the fusion of ilium, ischium and pubis that receives the head of the femur (4) Depression of the scapula that articulates with the head of the humerus","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"The glenoid cavity of the scapula forms the shoulder joint with the humerus; the acetabulum receives the femur; the acromion is the flat projection of the scapular spine; the patella is the knee cap.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-41","question":"Assertion (A): Prolonged hyperglycemia leads to diabetes mellitus, with loss of glucose in urine and formation of ketone bodies.\nReason (R): Diabetes mellitus is caused by excess secretion of glucagon.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true but R is false: diabetes mellitus is due to deficiency of insulin (or its action), and it is treated with insulin therapy.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-42","question":"How many of the following statements about the pituitary gland are correct?\n(i) The pars distalis secretes oxytocin and vasopressin.\n(ii) The pars intermedia secretes MSH.\n(iii) In humans, the pars intermedia is almost merged with the pars distalis.\n(iv) The neurohypophysis stores and releases hormones synthesised by the hypothalamus.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (ii), (iii) and (iv) are correct. The pars distalis produces GH, PRL, TSH, ACTH, LH and FSH; oxytocin and vasopressin are made by the hypothalamus and released from the neurohypophysis.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-43","question":"Which joint–location pair is INCORRECTLY matched?","options":["Hinge joint: knee joint","Pivot joint: between atlas and axis","Gliding joint: between the carpal and metacarpal of the thumb","Ball and socket joint: between the humerus and pectoral girdle"],"answer":2,"explanation":"The joint between the carpal and metacarpal of the thumb is a saddle joint; gliding joints occur between the carpals.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-44","question":"How many of the following statements about the mechanism of hormone action are correct?\n(i) Hormones binding to membrane-bound receptors generate second messengers such as cyclic AMP, IP₃ and Ca²⁺.\n(ii) Iodothyronines act through membrane-bound receptors and cyclic AMP.\n(iii) Hormone receptors are specific, each receptor being specific to one hormone only.\n(iv) FSH is a steroid hormone.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only (i) and (iii) are correct. Steroid hormones and iodothyronines act through intracellular receptors and regulate gene expression, and FSH is a glycoprotein.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-45","question":"Arrange the events of skeletal muscle contraction in the correct order.\n(i) Ca²⁺ is released from the sarcoplasmic reticulum\n(ii) Acetylcholine is released at the neuromuscular junction\n(iii) Ca²⁺ binds troponin and the active sites on actin are exposed\n(iv) An action potential spreads through the sarcolemma\n(v) The myosin head binds actin to form a cross bridge","options":["(ii), (iv), (i), (iii), (v)","(ii), (i), (iv), (iii), (v)","(ii), (iv), (iii), (i), (v)","(iv), (ii), (i), (iii), (v)"],"answer":0,"explanation":"ACh release at the motor end plate creates an action potential in the sarcolemma, which releases Ca²⁺ from the sarcoplasmic reticulum; Ca²⁺ binds troponin, unmasking actin, and myosin heads form cross bridges and pull the actin filaments.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-46","question":"The hormones secreted rapidly by the adrenal medulla in response to stress, often called emergency or 'fight or flight' hormones, are:","options":["Insulin and glucagon","Thyroxine and thyrocalcitonin","Adrenaline and noradrenaline","Cortisol and aldosterone"],"answer":2,"explanation":"Adrenaline (epinephrine) and noradrenaline (norepinephrine) are catecholamines of the adrenal medulla, secreted in response to any stress or emergency. Cortisol and aldosterone come from the adrenal cortex.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-47","question":"Each half of the human pectoral girdle consists of:","options":["The sternum and a pair of ribs","Humerus and radius","A clavicle and a scapula","Ilium, ischium and pubis"],"answer":2,"explanation":"Each half of the pectoral girdle has a clavicle (collar bone) and a scapula. The ilium, ischium and pubis fuse to form each coxal bone of the pelvic girdle.","difficulty":"easy","source":"NEET pattern"},
  {"id": "bio-neural-endocrine-48", "question": "The gaps between two adjacent myelin sheaths of a myelinated nerve fibre are called:", "options": ["Axon terminals", "Nissl's granules", "Nodes of Ranvier", "Synaptic clefts"], "answer": 2, "explanation": "In myelinated fibres, Schwann cells form the myelin sheath around the axon, and the gaps between adjacent sheaths are the nodes of Ranvier. Nissl's granules are in the cell body.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-neural-endocrine-49", "question": "The somatic neural system relays impulses from the CNS to:", "options": ["Only endocrine glands", "Involuntary organs and smooth muscles", "Skeletal muscles", "Only the heart"], "answer": 2, "explanation": "The PNS is divided into the somatic neural system, which relays impulses from the CNS to skeletal muscles, and the autonomic neural system, which relays them to involuntary organs and smooth muscles.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-neural-endocrine-50", "question": "The cranial meninges covering the human brain, from outside to inside, are:", "options": ["Pia mater, arachnoid, dura mater", "Arachnoid, dura mater, pia mater", "Dura mater, pia mater, arachnoid", "Dura mater, arachnoid, pia mater"], "answer": 3, "explanation": "The outer layer is the dura mater, the very thin middle layer is the arachnoid, and the inner layer in contact with brain tissue is the pia mater.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-neural-endocrine-51", "question": "In a sarcomere, the Z line bisects the:", "options": ["H zone", "I band", "A band", "M line"], "answer": 1, "explanation": "The I band (isotropic, light band) is bisected by an elastic fibre called the Z line, to which thin filaments are attached. The M line lies at the centre of the A band, holding thick filaments.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id":"bio-neural-endocrine-52","question":"Ciliary movement occurs in most of our internal tubular organs lined by ciliated epithelium. Which pair is correct?","options":["Heart and blood vessels","Leucocytes and tissue macrophages","Limbs and jaws","Trachea and fallopian tubes"],"answer":3,"explanation":"Coordinated ciliary movement in the trachea removes dust particles and in the fallopian tubes passes the ova. Leucocytes and macrophages show amoeboid movement, and limbs and jaws use muscular movement.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-53","question":"Hormones released by the hypothalamus reach the pituitary gland through:","options":["The lymphatic system","The spinal cord","The cerebrospinal fluid of ventricles","A portal circulatory system"],"answer":3,"explanation":"Hypothalamic releasing and inhibiting hormones originate in hypothalamic neurons, pass through axons and are released from their nerve endings, then reach the pituitary through a portal circulatory system to regulate the anterior pituitary.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-54","question":"Small amounts of androgenic steroids secreted by the adrenal cortex play a role in:","options":["Growth of axial, pubic and facial hair at puberty","Lowering blood calcium by promoting bone deposition","Milk ejection during breastfeeding","Spermatogenesis in the seminiferous tubules"],"answer":0,"explanation":"The adrenal cortex secretes small amounts of androgenic steroids that help in the growth of axial, pubic and facial hair during puberty. Spermatogenesis is controlled by FSH and androgens from the testis.","difficulty":"hard","source":"NEET pattern"},
  {"id": "bio-neural-endocrine-55", "question": "In old individuals, the production of thymosins decreases, resulting in weakened immune responses, because:", "options": ["The thymus begins producing insulin instead", "The pituitary stops producing TSH", "The thymus degenerates with age", "The thymus is converted into adrenal tissue"], "answer": 2, "explanation": "The thymus is degenerated in old individuals, reducing thymosin production. As thymosins are needed for the differentiation of T-lymphocytes and promote antibody production, immune responses weaken.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-neural-endocrine-56", "question": "Each myosin monomer (meromyosin) of the thick filament has two parts. The globular head with a short arm and the tail are respectively called:", "options": ["Light meromyosin (LMM) and heavy meromyosin (HMM)", "Troponin and tropomyosin", "F-actin and G-actin", "Heavy meromyosin (HMM) and light meromyosin (LMM)"], "answer": 3, "explanation": "The globular head with a short arm is heavy meromyosin (HMM), and the tail is light meromyosin (LMM). The head projects outward as a cross arm with ATPase activity.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-neural-endocrine-57", "question": "Osteoporosis, an age-related disorder characterised by decreased bone mass and increased chances of fractures, is commonly caused by:", "options": ["Excess of vitamin A", "Autoimmune attack on the neuromuscular junction", "Accumulation of uric acid crystals", "Decreased levels of estrogen"], "answer": 3, "explanation": "Decreased levels of estrogen are a common cause of osteoporosis. Uric acid crystals cause gout, and the autoimmune attack on the neuromuscular junction is myasthenia gravis.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-neural-endocrine-58", "question": "Each human rib has two articulation surfaces on its dorsal end and is therefore called:", "options": ["Biconcave", "Dicondylic", "Bicephalic", "Bipolar"], "answer": 2, "explanation": "Each rib is a thin flat bone connected dorsally to the vertebral column and ventrally to the sternum; having two articulation surfaces on its dorsal end, it is called bicephalic. 'Dicondylic' describes the skull with two occipital condyles.", "difficulty": "hard", "source": "NEET pattern"},
  {"id":"bio-neural-endocrine-59","question":"Repeated activation of skeletal muscle can cause fatigue mainly because of:","options":["Destruction of the Z lines by repeated stretching","Excess Ca²⁺ left in the sarcoplasm after contraction","Lactic acid from anaerobic breakdown of glycogen","Loss of myoglobin from the red fibres"],"answer":2,"explanation":"Repeated activation leads to accumulation of lactic acid from anaerobic breakdown of glycogen in the muscle, causing fatigue. Red fibres, rich in myoglobin and mitochondria, resist fatigue better.","difficulty":"hard","source":"NEET pattern"},
  {"id": "bio-neural-endocrine-60", "question": "The human axial skeleton has 80 bones. Which breakdown is correct?", "options": ["Skull 22, hyoid 1, ear ossicles 6, vertebrae 26, sternum 1, ribs 12", "Skull 22, vertebrae 26, sternum 1, ribs 24, girdles 7", "Skull 22, hyoid 1, ear ossicles 6, vertebrae 33, sternum 1, ribs 17", "Skull 22, hyoid 1, ear ossicles 6, vertebrae 26, sternum 1, ribs 24"], "answer": 3, "explanation": "22 skull bones + 1 hyoid + 6 ear ossicles (29 in the head), 26 vertebrae, 1 sternum and 12 pairs of ribs (24) add up to 29 + 26 + 1 + 24 = 80. Counting 12 ribs instead of 12 pairs, or 33 vertebrae (the child count), gives wrong totals, and girdles belong to the appendicular skeleton.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-neural-endocrine-61", "question": "Match the type of neuron or nerve fibre with where it is found.\nList I: (A) Multipolar neuron (B) Bipolar neuron (C) Unipolar neuron (D) Unmyelinated nerve fibre\nList II: (1) Retina of the eye (2) Cerebral cortex (3) Autonomous and somatic neural systems (4) Usually found in the embryonic stage", "options": ["A-1, B-2, C-4, D-3", "A-2, B-4, C-1, D-3", "A-2, B-1, C-3, D-4", "A-2, B-1, C-4, D-3"], "answer": 3, "explanation": "Multipolar neurons (one axon, two or more dendrites) occur in the cerebral cortex, bipolar neurons in the retina, unipolar neurons usually in the embryonic stage, and unmyelinated fibres are commonly found in the autonomous and somatic neural systems.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-neural-endocrine-62","question":"How many of the following statements about the adrenal gland are correct?\n(i) The adrenal medulla secretes adrenaline and noradrenaline, collectively called catecholamines.\n(ii) Catecholamines increase alertness, pupillary dilation, piloerection, sweating, heart beat and rate of respiration.\n(iii) The zona glomerulosa is the innermost layer of the adrenal cortex.\n(iv) Aldosterone acts on the renal tubules to stimulate reabsorption of Na⁺ and water and excretion of K⁺ and phosphate ions.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (ii) and (iv) are correct. (iii) is wrong: the adrenal cortex has an inner zona reticularis, a middle zona fasciculata and an outer zona glomerulosa.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-neural-endocrine-63", "question": "Assertion (A): The hypothalamus controls the secretions of the anterior pituitary.\nReason (R): Neurosecretory cells of the hypothalamus produce releasing hormones that stimulate, and inhibiting hormones that inhibit, the secretion of pituitary hormones.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. For example, GnRH stimulates gonadotropin release and somatostatin inhibits growth hormone release from the pituitary.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-neural-endocrine-64", "question": "Arrange the components of a reflex arc in the order in which an impulse passes through them:\n(i) Efferent neuron (ii) Sensory receptor (iii) Afferent neuron entering the CNS through the dorsal nerve root (iv) Effector", "options": ["(ii), (i), (iii), (iv)", "(ii), (iii), (i), (iv)", "(iii), (ii), (i), (iv)", "(i), (iii), (ii), (iv)"], "answer": 1, "explanation": "The receptor picks up the stimulus, the afferent neuron carries it through the dorsal nerve root into the CNS, and the efferent neuron carries the response from the CNS to the effector.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-neural-endocrine-65", "question": "Match the hormone with its target or action.\nList I: (A) GnRH (B) LH in males (C) FSH in males (D) TSH\nList II: (1) Stimulates synthesis and secretion of thyroid hormones (2) Stimulates the pituitary to synthesise and release gonadotropins (3) Acts on Leydig cells to stimulate synthesis and secretion of androgens (4) Regulates spermatogenesis along with androgens", "options": ["A-2, B-3, C-4, D-1", "A-3, B-2, C-4, D-1", "A-2, B-4, C-3, D-1", "A-2, B-3, C-1, D-4"], "answer": 0, "explanation": "GnRH from the hypothalamus stimulates gonadotropin release; LH acts on Leydig cells to produce androgens; FSH together with androgens regulates spermatogenesis; TSH stimulates the thyroid.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-neural-endocrine-66","question":"How many of the following statements about the hindbrain are correct?\n(i) The pons consists of fibre tracts that interconnect different regions of the brain.\n(ii) The cerebellum has a very convoluted surface to provide additional space for many more neurons.\n(iii) The medulla of the brain is connected to the spinal cord.\n(iv) The brain stem is formed by the cerebellum, pons and medulla oblongata.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (ii) and (iii) are correct. (iv) is wrong: the brain stem is formed by the midbrain, pons and medulla oblongata; the cerebellum is not part of it.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-67","question":"All of the following are functions of the hypothalamus EXCEPT:","options":["Control of the urge for eating and drinking (hunger, thirst)","Secretion of hormones that regulate the pituitary","Coordination of voluntary movements and body balance","Thermoregulation, i.e. control of body temperature"],"answer":2,"explanation":"The hypothalamus controls body temperature, hunger and thirst and secretes hypothalamic hormones. Coordinating voluntary movement and balance is a cerebellar function.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-neural-endocrine-68", "question": "Assertion (A): Tetany is characterised by rapid spasms (wild contractions) in muscle.\nReason (R): Tetany is caused by a high level of Ca²⁺ in the body fluid.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true. R is false: tetany is due to LOW Ca²⁺ in body fluid, which increases neuromuscular excitability, for example in hypoparathyroidism.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-neural-endocrine-69","question":"How many of the following statements about synapses are correct?\n(i) At an electrical synapse the membranes of the pre- and post-synaptic neurons are in very close proximity.\n(ii) At a chemical synapse the membranes are separated by a fluid-filled space called the synaptic cleft.\n(iii) Neurotransmitters released at a chemical synapse may produce either an excitatory or an inhibitory new potential in the post-synaptic neuron.\n(iv) Impulse transmission across an electrical synapse is faster than across a chemical synapse.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Membranes are very close at an electrical synapse and separated by a synaptic cleft at a chemical one; neurotransmitters may be excitatory or inhibitory; and transmission across an electrical synapse is always faster.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-neural-endocrine-70", "question": "Which pair of gland and hormone is INCORRECTLY matched?", "options": ["Corpus luteum — progesterone", "Thymus — thymosins", "Adrenal cortex — adrenaline", "Pineal gland — melatonin"], "answer": 2, "explanation": "Adrenaline is secreted by the adrenal medulla; the adrenal cortex secretes corticoids such as cortisol and aldosterone. The other three pairs are correct.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-neural-endocrine-71","question":"The brain stem of the human brain is formed by the:","options":["Cerebrum, thalamus and hypothalamus","Cerebellum, pons and medulla oblongata","Midbrain, pons and medulla oblongata","Thalamus, midbrain and cerebellum"],"answer":2,"explanation":"The midbrain, pons and medulla oblongata form the brain stem, which connects the brain to the spinal cord. The cerebellum is part of the hindbrain but is not included in the brain stem.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-72","question":"Which cells of the human body show amoeboid movement?","options":["Skeletal muscle fibres","Ciliated cells of the trachea","Neurons","Macrophages and leucocytes"],"answer":3,"explanation":"Macrophages and leucocytes move using pseudopodia formed by streaming of protoplasm, aided by microfilaments. Ciliated cells of the trachea show ciliary movement instead.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-73","question":"Deficiency of iodine in the diet results in hypothyroidism and enlargement of the thyroid gland, commonly called:","options":["Goitre","Acromegaly","Tetany","Myasthenia gravis"],"answer":0,"explanation":"Iodine is essential for making thyroid hormones; its deficiency causes hypothyroidism and an enlarged thyroid (goitre). Acromegaly is due to excess growth hormone in adults, and tetany is due to low Ca²⁺.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-74","question":"The human skull is composed of cranial and facial bones that total:","options":["22 bones: 8 cranial and 14 facial","22 bones: 14 cranial and 8 facial","29 bones: 8 cranial and 21 facial","28 bones: 8 cranial and 14 facial plus 6 ear ossicles"],"answer":0,"explanation":"The skull has 8 cranial bones, which form the brain case, and 14 facial bones, 22 in total. The U-shaped hyoid bone and the 6 ear ossicles are counted separately.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-75","question":"The joint between adjacent vertebrae in the vertebral column, which permits limited movement, is a:","options":["Fibrous joint","Cartilaginous joint","Synovial pivot joint","Synovial hinge joint"],"answer":1,"explanation":"Adjacent vertebrae are joined by cartilage (a cartilaginous joint), which allows limited movement. Fibrous joints such as the sutures between flat skull bones allow no movement, and synovial joints have a fluid-filled cavity.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-76","question":"The outermost layer of the adrenal cortex is the:","options":["Zona fasciculata","Zona reticularis","Zona glomerulosa","Adrenal medulla"],"answer":2,"explanation":"From outside to inside, the adrenal cortex has the zona glomerulosa, zona fasciculata (middle) and zona reticularis (inner). The medulla lies at the centre and secretes catecholamines.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-77","question":"In humans, the parathyroid glands are:","options":["Two, in front of the trachea, and secrete the hypocalcaemic calcitonin","Four, embedded in the thymus, and secrete thymosins","One pair, on top of the kidneys, and secrete aldosterone","Four, on the back of the thyroid, and secrete a hypercalcaemic hormone"],"answer":3,"explanation":"There are four parathyroid glands, one pair in each lobe of the thyroid on its back side. Their hormone PTH raises blood Ca²⁺ (hypercalcaemic). Calcitonin (TCT) comes from the thyroid itself and has the opposite effect.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-78","question":"The pituitary gland is located in a bony cavity called the:","options":["Foramen magnum, and is attached to the medulla","Sella turcica, and is attached to the hypothalamus","Acetabulum, and is attached to the pons by a stalk","Glenoid cavity, and is attached to the thalamus"],"answer":1,"explanation":"The pituitary sits in the sella turcica of the sphenoid region and hangs from the hypothalamus by a stalk. The foramen magnum is where the spinal cord leaves the skull; the acetabulum and glenoid cavity are joint sockets of the girdles.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-79","question":"When a stimulus increases the Na⁺ permeability at a site on an axon, rapid Na⁺ influx makes that site:","options":["Positive outside and negative inside (polarised)","Negative on both surfaces","Positive inside and negative outside (depolarised)","Hyperpolarised, so that it cannot conduct an impulse"],"answer":2,"explanation":"Inflow of Na⁺ reverses the polarity: the inner surface becomes positive and the outer negative, generating the action potential. The resting (polarised) state has a positive outer surface.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-80","question":"In a relaxed sarcomere, the central region of the A band that contains only thick (myosin) filaments, not overlapped by thin filaments, is the:","options":["I band","Z line","Entire A band","H zone"],"answer":3,"explanation":"The H zone is the central part of the thick filaments that thin filaments do not overlap. The I band contains only thin (actin) filaments, and the Z line bisects the I band.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-81","question":"Which statement about the thin (actin) filament of skeletal muscle is correct?","options":["Two helically wound F-actins (G-actin polymers) with tropomyosin along them","Each thin filament is a single G-actin monomer bound to troponin","Each thin filament is made of meromyosin monomers with globular heads","Tropomyosin masks the myosin-binding sites on actin only after Ca²⁺ binds troponin"],"answer":0,"explanation":"Two F-actin chains (polymers of G-actin) are wound together, two tropomyosin filaments run alongside, and troponin sits on tropomyosin at intervals. In the resting state troponin masks the binding sites; Ca²⁺ unmasks them rather than masking them.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-82","question":"Melanocyte stimulating hormone (MSH), which regulates skin pigmentation, is secreted by the:","options":["Pars intermedia of the pituitary","Pars nervosa (posterior pituitary)","Pineal gland, along with melatonin","Chromaffin cells of adrenal medulla"],"answer":0,"explanation":"MSH is the only hormone of the pars intermedia and acts on melanocytes. The pars nervosa only stores and releases hypothalamic oxytocin and vasopressin, and the pineal gland secretes melatonin.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-83","question":"In females, luteinising hormone (LH):","options":["Stimulates the growth and development of ovarian follicles only","Induces ovulation of the Graafian follicle and maintains corpus luteum","Causes milk ejection from the mammary glands during suckling","Is secreted by the corpus luteum to maintain the endometrium in pregnancy"],"answer":1,"explanation":"LH triggers ovulation and keeps the corpus luteum going. Follicle growth is mainly an FSH effect, milk ejection is caused by oxytocin, and the corpus luteum secretes progesterone, not LH.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-84","question":"The hormone that acts on the mammary glands to stimulate the formation of alveoli (sac-like structures that store milk) is:","options":["Oxytocin","Relaxin","Progesterone","Thyrocalcitonin"],"answer":2,"explanation":"Progesterone supports pregnancy and stimulates the formation of alveoli and milk secretion in the mammary glands. Oxytocin causes milk ejection but does not form alveoli, and relaxin acts during pregnancy and parturition.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-85","question":"The cerebrum wraps around a structure that is the major coordinating centre for sensory and motor signalling. This structure is the:","options":["Hypothalamus","Pons","Cerebellum","Thalamus"],"answer":3,"explanation":"The thalamus relays and coordinates sensory and motor signals. The hypothalamus lies at its base and controls body temperature, hunger and thirst and secretes neurohormones; the cerebellum coordinates movement and balance.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-86","question":"Large regions of the cerebral cortex that are neither clearly sensory nor motor are called association areas. They are responsible for:","options":["Control of respiration, heart rate and gastric secretion","Intersensory associations, memory and communication","Regulation of body temperature, hunger and thirst","Maintenance of posture and balance only"],"answer":1,"explanation":"Association areas handle complex functions such as linking senses, memory and communication. Respiration and gastric secretion are controlled by the medulla, temperature, hunger and thirst by the hypothalamus, and balance mainly by the cerebellum.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-87","question":"A canal that passes through the midbrain, whose dorsal portion bears four round swellings, is the:","options":["Central canal of the spinal cord","Corpus callosum","Cerebral aqueduct","Arachnoid space"],"answer":2,"explanation":"The cerebral aqueduct runs through the midbrain; the four dorsal swellings are the corpora quadrigemina. The corpus callosum is a band of nerve fibres joining the two cerebral hemispheres, not a canal.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-88","question":"The numbers of carpals (wrist bones) in one human forelimb and tarsals (ankle bones) in one hindlimb are respectively:","options":["7 and 8","5 and 5","8 and 8","8 and 7"],"answer":3,"explanation":"Each hand has 8 carpals, 5 metacarpals and 14 phalanges. Each foot has 7 tarsals, 5 metatarsals and 14 phalanges. 5 is the number of metacarpals or metatarsals.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-89","question":"In adult women, hypothyroidism may cause:","options":["The menstrual cycle to become irregular","Exophthalmic goitre with protruding eyeballs","Acromegaly","Diabetes insipidus"],"answer":0,"explanation":"NCERT notes that hypothyroidism can make the menstrual cycle irregular in adult women. Exophthalmic goitre is a form of hyperthyroidism, acromegaly is caused by excess GH, and diabetes insipidus by ADH deficiency.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-90","question":"Aldosterone, the main mineralocorticoid, acts mainly at the renal tubules and stimulates:","options":["Na⁺ and water reabsorption, and K⁺ and phosphate excretion","Na⁺ and water excretion, and K⁺ and phosphate reabsorption","Reabsorption of glucose and amino acids in the PCT","Secretion of renin by the juxtaglomerular cells"],"answer":0,"explanation":"Aldosterone retains Na⁺ and water and removes K⁺ and phosphate, which helps maintain electrolytes, body fluid volume, osmotic pressure and blood pressure. Renin is released in response to a fall in GFR, not stimulated by aldosterone.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-91","question":"How many of the following statements about the sliding of filaments during skeletal muscle contraction are correct?\n(i) The I bands get reduced in length.\n(ii) The A bands retain their length.\n(iii) The Z lines are pulled inwards, shortening the sarcomere.\n(iv) The thin and thick filaments themselves become shorter.\n(v) The myosin cross bridges pull the actin filaments towards the centre of the A band.","options":["One","Two","Three","Four"],"answer":3,"explanation":"Statements (i), (ii), (iii) and (v) are correct. (iv) is false: the filaments keep their length and only slide past each other, which is the basis of the sliding filament theory.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-92","question":"During the cross-bridge cycle of skeletal muscle contraction, the cross bridge between the myosin head and actin is broken when:","options":["ADP and Pi are released from the myosin head","Ca²⁺ binds to troponin","A new ATP molecule binds to the myosin head","Acetylcholine is released at the motor end plate"],"answer":2,"explanation":"Release of ADP and Pi goes with the power stroke. A new ATP must then bind to detach the head from actin, and its hydrolysis re-energises the head for the next cycle. Ca²⁺ binding to troponin allows cross bridges to form; it does not break them.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-93","question":"Match the endocrine gland with its location.\nList I: (A) Pineal (B) Thyroid (C) Thymus (D) Adrenal\nList II: (1) Between the lungs, behind the sternum, on the ventral side of the aorta (2) At the anterior part of each kidney (3) Dorsal side of the forebrain (4) Two lobes on either side of the trachea joined by an isthmus","options":["A-3, B-1, C-4, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1"],"answer":2,"explanation":"The pineal gland is on the dorsal side of the forebrain, and the thyroid's two lobes flank the trachea, joined by an isthmus. The thymus lies between the lungs behind the sternum, and the adrenals sit at the anterior part of each kidney.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-94","question":"Assertion (A): Impulse transmission across an electrical synapse is faster than across a chemical synapse.\nReason (R): At a chemical synapse, neurotransmitters must be released into the synaptic cleft and bind to receptors on the post-synaptic membrane before a new potential develops.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"At an electrical synapse current flows directly from one neuron to the next. A chemical synapse adds the steps of transmitter release, diffusion across the cleft and receptor binding, which slow it down. R therefore explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-95","question":"The human axial skeleton has 80 bones. How many bones make up the appendicular skeleton (limbs and girdles)?","options":["120","206","126","130"],"answer":2,"explanation":"Each limb has 30 bones, so the four limbs have 120. The pectoral girdle has 4 bones (2 clavicles + 2 scapulae) and the pelvic girdle 2 coxal bones, giving 120 + 6 = 126. Check: 80 + 126 = 206.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-96","question":"How many of the following statements about pancreatic hormones are correct?\n(i) Glucagon stimulates glycogenolysis in hepatocytes, raising blood sugar.\n(ii) Glucagon stimulates gluconeogenesis.\n(iii) Glucagon reduces cellular glucose uptake and utilisation.\n(iv) Insulin enhances glucose uptake by hepatocytes and adipocytes.\n(v) Insulin stimulates glycogenolysis in the liver.","options":["One","Two","Three","Four"],"answer":3,"explanation":"Statements (i) to (iv) are correct. (v) is false: insulin stimulates glycogenesis (glucose to glycogen), which is how it lowers blood glucose. Glycogenolysis is a glucagon effect.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-97","question":"During a thyroid operation, a patient's parathyroid glands are accidentally removed. Within days the patient is most likely to show:","options":["Low blood Ca²⁺ with muscle spasms (tetany)","High blood Ca²⁺, with bone loss and kidney stones","Exophthalmic goitre with weight loss","Diabetes insipidus with dilute urine"],"answer":0,"explanation":"Without PTH, bone resorption and Ca²⁺ reabsorption fall, so blood Ca²⁺ drops. Low Ca²⁺ in body fluids causes tetany, rapid spasms of muscle. Excess PTH, not lack of it, would raise blood Ca²⁺.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-98","question":"A person takes high doses of thyroxine for a long time. The expected change in the secretion of TSH from the anterior pituitary is:","options":["A decrease, as high thyroxine inhibits TSH release","An increase, to match the high thyroxine level","No change, because TSH is controlled only by the hypothalamus","An increase, followed by enlargement of the thyroid"],"answer":0,"explanation":"High circulating thyroid hormone feeds back to inhibit TRH and TSH release, so TSH falls and the person's own thyroid becomes less active. Rising TSH with thyroid enlargement is the picture of iodine deficiency.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-99","question":"How many of the following pairs of hormones act antagonistically on the same physiological parameter?\n(i) Insulin and glucagon\n(ii) Parathyroid hormone and thyrocalcitonin\n(iii) ANF and the renin–angiotensin mechanism\n(iv) FSH and LH\n(v) Oxytocin and vasopressin","options":["1 pair","2 pairs","3 pairs","4 pairs"],"answer":2,"explanation":"Pairs (i) (blood glucose), (ii) (blood Ca²⁺) and (iii) (blood pressure; ANF acts as a check on the renin–angiotensin mechanism) are antagonistic. FSH and LH work together on the gonads, and oxytocin and vasopressin act on different targets.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-100","question":"Arrange the events of conduction of a nerve impulse at one site of an axon in the correct order:\n(i) The stimulus makes the membrane freely permeable to Na⁺\n(ii) Na⁺ rushes in, making the inner surface positive\n(iii) Permeability to K⁺ increases and K⁺ diffuses out\n(iv) The resting potential is restored and the fibre is ready for the next impulse","options":["(i), (iii), (ii), (iv)","(i), (ii), (iii), (iv)","(iii), (i), (ii), (iv)","(ii), (i), (iii), (iv)"],"answer":1,"explanation":"Na⁺ permeability rises first and Na⁺ influx depolarises the membrane. Then K⁺ outflow repolarises it, restoring the resting potential so the fibre can respond to the next stimulus.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-neural-endocrine-101","question":"Match the type of neuron with where it is found, as given in NCERT.\nList I: (A) Multipolar (B) Bipolar (C) Unipolar\nList II: (1) Usually found in the embryonic stage (2) Retina of the eye (3) Cerebral cortex","options":["A-3, B-2, C-1","A-2, B-3, C-1","A-3, B-1, C-2","A-1, B-2, C-3"],"answer":0,"explanation":"Multipolar neurons (one axon, two or more dendrites) occur in the cerebral cortex, bipolar neurons (one axon, one dendrite) in the retina, and unipolar neurons (cell body with one axon only) are usually found in the embryonic stage.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-102","question":"In a neuron, Nissl's granules are present in:","options":["the cell body and the axon, but not in the dendrites","the cell body and the dendrites, but not in the axon","the axon terminals and the synaptic knobs only","the myelin sheath formed around the axon"],"answer":1,"explanation":"The cell body contains granular Nissl's bodies, and the short branched dendrites projecting from it also contain Nissl's granules; the axon does not, which is one way the two kinds of fibres differ.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-103","question":"Which statement about non-myelinated nerve fibres is correct as per NCERT?","options":["They lack Schwann cells completely and are found only in the brain","They are found mainly in the spinal nerves and the cranial nerves","They have nodes of Ranvier at regular intervals along the axon","They are enclosed by Schwann cells that form no myelin sheath"],"answer":3,"explanation":"An unmyelinated fibre is enclosed by a Schwann cell that does not form a myelin sheath, and such fibres are common in the autonomous and somatic neural systems. Myelinated fibres (with nodes of Ranvier) occur in spinal and cranial nerves.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-104","question":"In a resting neuron, which correctly describes the ionic distribution across the axonal membrane?","options":["Axoplasm has high Na⁺ and low K⁺; the outside fluid has high K⁺ and low Na⁺","Both sides have equal K⁺, but the axoplasm holds more Na⁺ than the outside fluid","Axoplasm: high K⁺, negative proteins, low Na⁺; outside: high Na⁺, low K⁺","Outside fluid has high K⁺ and negative proteins, and the axoplasm has high Na⁺"],"answer":2,"explanation":"The axoplasm has a high K⁺ concentration and negatively charged proteins but little Na⁺, while the fluid outside has low K⁺ and high Na⁺, forming a concentration gradient maintained by the Na⁺/K⁺ pump.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-105","question":"At a chemical synapse, binding of neurotransmitters to receptors on the post-synaptic membrane:","options":["always generates an excitatory potential in the post-synaptic neuron","directly pumps Ca²⁺ into the post-synaptic neuron through ion pumps","makes synaptic vesicles of the post-synaptic neuron fuse with its membrane","opens ion channels, and the new potential may be excitatory or inhibitory"],"answer":3,"explanation":"Neurotransmitter binding opens ion channels in the post-synaptic membrane, allowing ions in; the new potential may be excitatory or inhibitory. Synaptic vesicles belong to the pre-synaptic axon terminal.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-106","question":"The visceral nervous system is best described as:","options":["the PNS nerves, fibres, ganglia and plexuses between CNS and viscera","the part of the CNS formed only by the medulla, the pons and hypothalamus","the somatic part of the PNS relaying impulses from CNS to skeletal muscles","the part of the PNS made only of afferent fibres from viscera to the CNS"],"answer":0,"explanation":"NCERT defines the visceral nervous system as the part of the PNS comprising the whole complex of nerves, fibres, ganglia and plexuses by which impulses travel from the CNS to the viscera and from the viscera to the CNS — in both directions.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-107","question":"The cranial meninges covering the human brain, in order from outside to inside, are:","options":["pia mater, arachnoid, dura mater","dura mater, arachnoid, pia mater","arachnoid, dura mater, pia mater","dura mater, pia mater, arachnoid"],"answer":1,"explanation":"The outer layer is the dura mater, the very thin middle layer is the arachnoid, and the inner pia mater is in contact with the brain tissue.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-neural-endocrine-108","question":"The cerebellum has a very convoluted surface. According to NCERT, this:","options":["allows it to house the centres of respiration and gastric secretion","helps it connect the two cerebral hemispheres through fibre tracts","provides additional space for many more neurons","forms the cerebral aqueduct running through the hindbrain"],"answer":2,"explanation":"The cerebellum's convoluted surface provides additional space for many more neurons. Respiratory and gastric centres lie in the medulla, the corpus callosum joins the hemispheres, and the cerebral aqueduct passes through the midbrain.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-109","question":"Which grouping of brain parts is correct?","options":["Forebrain — cerebrum, thalamus and pons","Hindbrain — pons, cerebellum and hypothalamus","Midbrain — corpora quadrigemina, crura cerebri and cerebellum","Hindbrain — pons, cerebellum and medulla oblongata"],"answer":3,"explanation":"The forebrain has the cerebrum, thalamus and hypothalamus; the midbrain bears the corpora quadrigemina; the hindbrain comprises pons, cerebellum and medulla (also called medulla oblongata).","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-neural-endocrine-110","question":"Which statement about hypothalamic control of the pituitary gland is correct?","options":["Hypothalamic hormones reach the adenohypophysis through a portal circulatory system","The neurohypophysis is controlled by releasing hormones carried in the blood from the hypothalamus","GnRH from the hypothalamus inhibits the synthesis and release of pituitary gonadotrophins","Oxytocin and vasopressin are synthesised in the neurohypophysis and only stored in the hypothalamus"],"answer":0,"explanation":"Hypothalamic releasing and inhibiting hormones reach the anterior pituitary through a portal circulatory system, while the posterior pituitary is under direct neural regulation. GnRH stimulates gonadotrophin release, and oxytocin and vasopressin are made in the hypothalamus and stored in the neurohypophysis.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-111","question":"Over-secretion of growth hormone before puberty, and low secretion of growth hormone in a child, result respectively in:","options":["acromegaly and cretinism","gigantism and pituitary dwarfism","gigantism and cretinism","acromegaly and pituitary dwarfism"],"answer":1,"explanation":"Excess GH in childhood causes gigantism and low GH causes stunted growth (pituitary dwarfism). Acromegaly results from excess GH in adults, and cretinism from thyroid hormone deficiency in the foetus or child.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-112","question":"In human males, which statement correctly gives the roles of LH and FSH?","options":["LH by itself regulates spermatogenesis, while FSH stimulates androgen synthesis","LH and FSH both act only on Leydig cells, stimulating them to produce testosterone","LH stimulates androgen synthesis; FSH with androgens regulates spermatogenesis","FSH maintains the corpus luteum, while LH induces milk formation in mammary glands"],"answer":2,"explanation":"In males, LH stimulates the synthesis and secretion of androgens from the testis, while FSH together with androgens regulates spermatogenesis. Maintaining the corpus luteum is an LH role in females, and milk formation is driven by prolactin.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-113","question":"Melatonin from the pineal gland influences all of the following EXCEPT:","options":["the sleep–wake cycle and body temperature","metabolism, pigmentation and the menstrual cycle","our defence capability","the calcium level of blood plasma"],"answer":3,"explanation":"Melatonin regulates the 24-hour (diurnal) rhythm, such as sleep–wake cycle and body temperature, and also influences metabolism, pigmentation, the menstrual cycle and defence capability. Blood calcium is controlled by PTH and thyrocalcitonin.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-114","question":"Which statement about the human thymus is correct?","options":["Thymosins also promote antibody production (humoral immunity)","It lies on the dorsal side of the aorta, between the two kidneys","It grows larger in old age, making immune responses stronger then","Its hormones mainly regulate the diurnal rhythm of the body"],"answer":0,"explanation":"Thymosins drive differentiation of T-lymphocytes (cell-mediated immunity) and also promote antibody production (humoral immunity). The thymus lies behind the sternum on the ventral side of the aorta and degenerates in old age, weakening immunity.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-115","question":"Which of the following is NOT an effect of adrenaline and noradrenaline during an emergency?","options":["Increased alertness and piloerection","Constriction of the pupils","Increased rate of respiration","Breakdown of glycogen, lipids and proteins"],"answer":1,"explanation":"The catecholamines cause pupillary DILATION, along with alertness, piloerection, sweating, faster heartbeat and breathing, and breakdown of glycogen, lipids and proteins.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-116","question":"The three layers of the adrenal cortex, from the innermost to the outermost, are:","options":["zona glomerulosa, zona fasciculata, zona reticularis","zona fasciculata, zona reticularis, zona glomerulosa","zona reticularis, zona fasciculata, zona glomerulosa","zona reticularis, zona glomerulosa, zona fasciculata"],"answer":2,"explanation":"The cortex has an inner zona reticularis, a middle zona fasciculata and an outer zona glomerulosa. Option A lists the same layers outer to inner, a common reversal trap.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-117","question":"Small amounts of androgenic steroids secreted by the human adrenal cortex play a role in:","options":["development of the testes and spermatogenesis in males","maintenance of the corpus luteum in females","gluconeogenesis, lipolysis and proteolysis","growth of axial, pubic and facial hair at puberty"],"answer":3,"explanation":"NCERT states that the adrenal cortex secretes small amounts of androgenic steroids, which play a role in the growth of axial hair, pubic hair and facial hair during puberty. Gluconeogenesis, lipolysis and proteolysis are glucocorticoid actions.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-118","question":"According to NCERT, the human pancreas contains about how many islets of Langerhans, and what share of the pancreatic tissue do they form?","options":["1–2 million; only 1–2 per cent","1–2 lakh; about 10–20 per cent","1–2 million; about 20–30 per cent","10–20 million; nearly 50 per cent"],"answer":0,"explanation":"A normal human pancreas has about 1 to 2 million islets of Langerhans, representing only 1 to 2 per cent of the pancreatic tissue; the rest is the exocrine part.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-119","question":"Which of the following is NOT an effect of androgens in human males?","options":["Anabolic effects on protein and carbohydrate metabolism","Formation of alveoli in the mammary glands","Influence on male sexual behaviour (libido) through the CNS","Maturation of the epididymis, vas deferens and seminal vesicles"],"answer":1,"explanation":"Androgens regulate the male accessory sex organs, act on the CNS to influence libido, and have anabolic effects on protein and carbohydrate metabolism. Formation of mammary alveoli is stimulated by progesterone in females.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-120","question":"Hormones that bind membrane-bound receptors generate second messengers inside the cell. Which set contains ONLY second messengers named in NCERT?","options":["cAMP, insulin and Ca²⁺","Thyroxine, IP₃ and cAMP","cAMP, IP₃ and Ca²⁺","Cortisol, cAMP and Na⁺"],"answer":2,"explanation":"NCERT names cyclic AMP, IP₃ and Ca²⁺ as second messengers. Insulin is a hormone (first messenger), while thyroxine and cortisol act through intracellular receptors.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-neural-endocrine-121","question":"Which of the following is NOT a function attributed to estrogens in NCERT?","options":["Development of the growing ovarian follicles","Appearance of the female secondary sex characters","Regulation of female sexual behaviour","Support of pregnancy after implantation"],"answer":3,"explanation":"Estrogens stimulate growth of female secondary sex organs, development of growing ovarian follicles, female secondary sex characters, mammary gland development and female sexual behaviour. Support of pregnancy is the role of progesterone.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-122","question":"Which type of movement is correctly matched with its example?","options":["Ciliary — passage of ova through the fallopian tubes","Amoeboid — removal of dust particles from the trachea","Muscular — movement of macrophages through the tissues","Ciliary — movement of the jaws, the tongue and the limbs"],"answer":0,"explanation":"Ciliary movement removes dust from the trachea and moves ova through the female reproductive tract. Macrophages and leucocytes show amoeboid movement, while jaws, tongue and limbs move by muscular movement.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-neural-endocrine-123","question":"A skeletal muscle fibre is called a syncytium because:","options":["its sarcoplasmic reticulum stores Ca²⁺ ions","its sarcoplasm contains many nuclei","many fibres are held together by fascia","its myofibrils show light and dark bands"],"answer":1,"explanation":"The sarcoplasm of a muscle fibre contains many nuclei, so the fibre is a syncytium. Ca²⁺ storage, the fascia binding fascicles and the striations are real features but do not explain the term.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-124","question":"Each monomeric meromyosin of a thick filament has two parts. Heavy meromyosin (HMM) and light meromyosin (LMM) are, respectively:","options":["the tail, and the globular head with a short arm","the troponin complex, and the tropomyosin strand","the globular head with a short arm, and the tail","the ATPase site alone, and the actin-binding site"],"answer":2,"explanation":"Each meromyosin has a globular head with a short arm (HMM) and a tail (LMM). The head and arm project outwards as the cross arm and carry the ATPase, ATP-binding and actin-binding sites.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-125","question":"Which statement about the banding pattern of a myofibril is correct?","options":["The A band contains actin and is called the isotropic band","The Z line lies in the middle of the A band and holds thick filaments","The M line bisects each I band and holds the thin filaments","The Z line bisects the I band, and thin filaments are attached to it"],"answer":3,"explanation":"The elastic Z line bisects each I band and the thin filaments are firmly attached to it; the M line holds the thick filaments together in the middle of the A band. The A band (myosin) is anisotropic, the I band (actin) isotropic.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-126","question":"A motor unit consists of:","options":["one motor neuron and the muscle fibres connected to it","one muscle fibre and all motor neurons supplying it","one sarcomere lying between two successive Z lines","the sarcolemma and the sarcoplasmic reticulum of a fibre"],"answer":0,"explanation":"A motor neuron along with the muscle fibres connected to it constitutes a motor unit; its junction with the sarcolemma is the neuromuscular junction or motor end-plate.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-neural-endocrine-127","question":"Repeated activation of skeletal muscles can lead to fatigue. As per NCERT, this is due to:","options":["depletion of Ca²⁺ stores in the sarcoplasmic reticulum","lactic acid from anaerobic breakdown of glycogen","uric acid crystals building up in the synovial fluid","loss of myoglobin from the red fibres of the muscle"],"answer":1,"explanation":"Repeated activation leads to accumulation of lactic acid from anaerobic breakdown of glycogen, causing fatigue. Uric acid crystals in joints cause gout.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-128","question":"How many bones are there in the human head region if the skull, the hyoid and the ear ossicles of both ears are counted together?","options":["22","23","29","28"],"answer":2,"explanation":"The skull has 22 bones (8 cranial + 14 facial), the hyoid is 1, and each middle ear has 3 ossicles (malleus, incus, stapes), giving 22 + 1 + 6 = 29. Forgetting the hyoid gives 28.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-129","question":"What is the total number of carpals, metacarpals and phalanges in BOTH hands of an adult human?","options":["52","27","60","54"],"answer":3,"explanation":"Each hand has 8 carpals, 5 metacarpals and 14 phalanges = 27; both hands have 54. The 52 trap uses the 7 tarsals of the foot instead (7 + 5 + 14 = 26 per foot).","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-130","question":"Human ribs are called bicephalic because each rib:","options":["has two articulation surfaces on its dorsal end","joins both the vertebral column and the sternum","is formed by the fusion of two separate bones","articulates with two adjacent ribs at its ends"],"answer":0,"explanation":"Each rib has two articulation surfaces on its dorsal end, hence 'bicephalic'. Being connected dorsally to the vertebral column and ventrally to the sternum is true for true ribs but is not the reason for the name.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-131","question":"The scapula is a large, triangular flat bone situated in the dorsal part of the thorax between the:","options":["first and fifth ribs","second and seventh ribs","fourth and tenth ribs","seventh and twelfth ribs"],"answer":1,"explanation":"NCERT describes the scapula as a large triangular flat bone in the dorsal part of the thorax between the second and the seventh ribs; its spine ends in the acromion, and the glenoid cavity receives the head of the humerus.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-132","question":"Which disorder is correctly matched with its description?","options":["Tetany — autoimmune disorder affecting the neuromuscular junction","Osteoporosis — inflammation of joints due to uric acid crystals","Tetany — rapid spasms in muscle due to low Ca²⁺ in body fluid","Muscular dystrophy — decreased bone mass due to low estrogen"],"answer":2,"explanation":"Tetany is rapid spasms (wild contractions) due to low Ca²⁺ in body fluid. Myasthenia gravis is the autoimmune NMJ disorder, gout is caused by uric acid crystals, and osteoporosis involves decreased bone mass often linked to low estrogen.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-neural-endocrine-133","question":"The human skull articulates with the superior region of the vertebral column through:","options":["one occipital condyle and the axis vertebra","a pivot joint between the hyoid and the atlas","two occipital condyles and the axis vertebra","two occipital condyles and the atlas vertebra"],"answer":3,"explanation":"The skull is dicondylic: its two occipital condyles articulate with the first vertebra, the atlas. The atlas–axis joint below it is a pivot joint that allows the head to turn.","difficulty":"hard","source":"NEET UG"},
];

export default questions;
